// Some portions generated by Codex

const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const vm = require('node:vm');
const { workbenchScriptPath } = require('./workbench-scripts.js');
const { FakeDocument } = require('./browser-fakes.js');
const { createMemoryRowStore } = require('./explore-section-fixtures.js');

const row = value => [{ kind: 'iri', value: `urn:value:${value}` }];
const failureMessage = 'Injected identity worker failure';

function harness(failOperation) {
    const workers = [];
    class IdentityWorker {
        constructor() {
            this.listeners = new Map();
            this.keys = new Set();
            this.baselineRows = 0;
            this.messages = [];
            this.terminated = false;
            this.failOperation = workers.length === 0 ? failOperation : null;
            workers.push(this);
        }
        addEventListener(type, callback) {
            this.listeners.set(type, [...(this.listeners.get(type) || []), callback]);
        }
        removeEventListener(type, callback) {
            this.listeners.set(type, (this.listeners.get(type) || []).filter(value => value !== callback));
        }
        fail() {
            for (const callback of [...(this.listeners.get('error') || [])]) {
                callback({ message: failureMessage });
            }
        }
        postMessage(message) {
            this.messages.push(message);
            // Browser workers discard cloneable messages after termination without throwing or replying.
            if (this.terminated) return;
            queueMicrotask(() => {
                if (this.terminated) return;
                if (message.op === this.failOperation) { this.fail(); return; }
                if (message.op === this.holdOperation) { this.held = message; return; }
                const response = { requestId: message.requestId, indexId: message.indexId, ok: true };
                if (message.op === 'identity-add') {
                    response.addedBytes = 0;
                    for (const key of message.keys) {
                        if (!this.keys.has(key)) {
                            this.keys.add(key);
                            response.addedBytes += key.length * 2 + 16;
                        }
                    }
                    this.baselineRows += message.keys.length;
                    response.baselineRows = this.baselineRows;
                } else if (message.op === 'identity-filter') {
                    response.unseen = message.keys.map((key, index) => this.keys.has(key) ? -1 : index)
                        .filter(index => index >= 0);
                } else if (message.op === 'identity-dispose') {
                    this.keys.clear();
                    response.disposed = true;
                }
                for (const callback of this.listeners.get('message') || []) callback({ data: response });
            });
        }
        terminate() { this.terminated = true; this.keys.clear(); }
    }
    const document = new FakeDocument();
    const window = { Worker: IdentityWorker, addEventListener() {}, removeEventListener() {} };
    document.defaultView = window;
    const context = vm.createContext({ workbench: {}, window, document, URL, URLSearchParams,
        AbortController, TextDecoder, setTimeout, clearTimeout });
    for (const name of ['queryStream.js', 'explore.js']) {
        vm.runInContext(fs.readFileSync(workbenchScriptPath(name), 'utf8'), context);
    }
    return { api: context.workbench.queryStream, explore: context.workbench.explore, workers };
}

async function nextTurn() { await new Promise(resolve => setImmediate(resolve)); }

async function settles(promise) {
    // These worker fixtures reply through microtasks. A whole turn is enough to drain their promise chains;
    // a missing reply must fail this assertion rather than leave the test runner waiting on a dead worker.
    const result = await Promise.race([
        promise.then(value => ({ status: 'fulfilled', value }), error => ({ status: 'rejected', error })),
        new Promise(resolve => setImmediate(() => resolve({ status: 'pending' })))
    ]);
    assert.equal(result.status, 'fulfilled', result.error && result.error.message
        || 'Identity worker cleanup must settle without another worker reply');
    return result.value;
}

for (const operation of ['identity-add', 'identity-filter']) {
    test(`identity disposal settles after a worker error during ${operation}`, async () => {
        const { api, workers } = harness();
        const budget = api.createRowStoreBudget(1024 * 1024);
        const index = await api.createRowIdentityIndex('server/repository', budget);
        await index.add([row('baseline')]);
        workers[0].failOperation = operation;
        const pending = operation === 'identity-add' ? index.add([row('new')]) : index.filter([row('new')]);
        await assert.rejects(pending, /Injected identity worker failure/);
        assert.equal(budget.usedBytes, 0);
        assert.equal(workers[0].terminated, true);

        const disposal = index.dispose();
        assert.equal(index.dispose(), disposal, 'repeated disposal shares the same completion');
        await settles(disposal);
        await settles(index.dispose());
        assert.equal(workers[0].messages.some(message => message.op === 'identity-dispose'), false,
            'a closed worker must never receive another disposal request');
        assert.equal(budget.usedBytes, 0);
        await assert.rejects(index.add([row('late')]), /disposed/);
        await assert.rejects(index.filter([row('late')]), /disposed/);
    });
}

test('an idle worker error before queued disposal prevents any new message', async () => {
    const { api, workers } = harness();
    const budget = api.createRowStoreBudget(1024 * 1024);
    const index = await api.createRowIdentityIndex('server/repository', budget);
    await index.add([row('baseline')]);
    const disposal = index.dispose();
    workers[0].fail();
    await settles(disposal);
    assert.equal(workers[0].messages.some(message => message.op === 'identity-dispose'), false);
    assert.equal(budget.usedBytes, 0);
});

test('disposal queued behind an operation settles when its worker errors', async () => {
    const { api, workers } = harness();
    const budget = api.createRowStoreBudget(1024 * 1024);
    const index = await api.createRowIdentityIndex('server/repository', budget);
    await index.add([row('baseline')]);
    workers[0].holdOperation = 'identity-filter';
    const rejected = assert.rejects(index.filter([row('new')]), /Injected identity worker failure/);
    await nextTurn();
    assert.equal(workers[0].held.op, 'identity-filter');
    const disposal = index.dispose();
    workers[0].fail();
    await rejected;
    await settles(disposal);
    assert.equal(workers[0].messages.some(message => message.op === 'identity-dispose'), false);
    assert.equal(budget.usedBytes, 0);
});

test('an error while awaiting the disposal acknowledgement still completes cleanup', async () => {
    const { api, workers } = harness();
    const budget = api.createRowStoreBudget(1024 * 1024);
    const index = await api.createRowIdentityIndex('server/repository', budget);
    await index.add([row('baseline')]);
    workers[0].holdOperation = 'identity-dispose';
    const disposal = index.dispose();
    await nextTurn();
    assert.equal(workers[0].held.op, 'identity-dispose');
    workers[0].fail();
    await settles(disposal);
    await settles(index.dispose());
    assert.equal(budget.usedBytes, 0);
    assert.equal(workers[0].terminated, true);
});

for (const operation of ['identity-add', 'identity-filter']) {
    test(`Explore preserves its cache and retries after an identity worker error during ${operation}`, async () => {
        const { api, explore, workers } = harness(operation);
        const budget = api.createRowStoreBudget(16 * 1024 * 1024);
        const initial = Array.from({ length: 10000 }, (_, index) => row(index));
        const changes = [];
        const controller = explore.createSectionController({
            url: 'https://example.test/workbench/repositories/r/explore?resource=%3Curn%3Ar%3E',
            repositoryScope: 'server/repository', memoryBudget: budget, fetcher: async () => ({}),
            onChange: () => {
                const section = controller.sections.types;
                changes.push({ loadingMore: section.loadingMore, error: section.error });
            },
            loadModel: async (_fetcher, rawUrl, _signal, options) => {
                const url = new URL(rawUrl);
                const section = url.searchParams.get('section');
                let rows = section === 'types' && url.searchParams.get('kind') === 'rows'
                    ? (url.searchParams.get('load') === 'more' ? [row(9999), row(10000), row(10001)] : initial)
                    : [];
                if (options.filterRows) rows = await options.filterRows(rows);
                return { rowStore: createMemoryRowStore(rows), rowCount: rows.length, vars: ['value'],
                    metadata: { 'explore-count': section === 'types' ? '10002' : '0' } };
            }
        });
        try {
            controller.start();
            await nextTurn();
            const section = controller.sections.types;
            assert.equal(section.status, 'ready');
            const original = section.store;
            await settles(controller.expand('types'));
            assert.equal(section.store, original, 'the failed attempt must not replace the committed cache');
            assert.equal(original.disposed, false);
            assert.equal(section.totalRows, 10000);
            assert.equal(section.loadingMore, false);
            assert.match(section.error, /Injected identity worker failure/);
            assert.ok(changes.some(change => !change.loadingMore && change.error === failureMessage),
                'the view is notified of the recoverable error with the busy state cleared');
            assert.equal(budget.usedBytes, 0);
            assert.equal(workers.length, 1);
            assert.equal(workers[0].terminated, true);

            await settles(controller.expand('types'));
            assert.equal(workers.length, 2, 'retry must create a fresh identity worker');
            assert.equal(section.totalRows, 10002);
            assert.equal(section.expanded, true);
            assert.equal(section.loadingMore, false);
            assert.equal(section.error, '');
            assert.equal((await section.store.read(10000, 2))[1][0].value, 'urn:value:10001');
            assert.equal(budget.usedBytes, 0);
            assert.equal(workers[1].terminated, true);
        } finally {
            controller.dispose();
        }
    });
}
